function alternarTema(){const t=document.body,e=document.getElementById("theme-icon");"light"===t.getAttribute("data-theme")?(t.setAttribute("data-theme","dark"),e.textContent="☀️",localStorage.setItem("theme","dark")):(t.setAttribute("data-theme","light"),e.textContent="🌙",localStorage.setItem("theme","light"))}function toggleMenu(){document.getElementById("nav-menu").classList.toggle("active"),document.querySelector(".overlay").classList.toggle("active")}function atualizarTextoBotao(){const t=document.getElementById("tipo").value,e=document.getElementById("btnCalcular");"parte"===t&&(e.textContent="Calcular Porcentagem"),"aumento"===t&&(e.textContent="Calcular Aumento"),"desconto"===t&&(e.textContent="Calcular Desconto")}function calcularPorcentagem(){const t=document.getElementById("tipo").value,e=parseFloat(document.getElementById("percentual").value),n=parseFloat(document.getElementById("valor").value),o=document.getElementById("resultado-area"),a=document.getElementById("result-value"),l=document.getElementById("result-desc-text"),r=document.getElementById("steps-text");if(o.style.display="none",isNaN(e)||isNaN(n))return void alert("Por favor, preencha a porcentagem e o valor corretamente.");let c=0,m="",u="";const d=t=>t.toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});if("parte"===t?(c=e/100*n,m=`${e}% de ${d(n)} é:`,u=`\n                    <strong>Cálculo:</strong><br>\n                    (Valor × %) / 100<br>\n                    (${d(n)} × ${e}) / 100<br>\n                    = <strong>${d(c)}</strong>\n                `):"aumento"===t?(c=n+e/100*n,m=`${d(n)} com aumento de ${e}% fica:`,u=`\n                    <strong>Cálculo:</strong><br>\n                    Valor × (1 + %/100)<br>\n                    ${d(n)} × (1 + ${e}/100)<br>\n                    = <strong>${d(c)}</strong>\n                `):"desconto"===t&&(c=n-e/100*n,m=`${d(n)} com desconto de ${e}% fica:`,u=`\n                    <strong>Cálculo:</strong><br>\n                    Valor × (1 - %/100)<br>\n                    ${d(n)} × (1 - ${e}/100)<br>\n                    = <strong>${d(c)}</strong>\n                `),o.style.display="block",a.textContent=d(c),l.textContent=m,r.innerHTML=u,"function"==typeof window.salvarCalculo){const o="parte"===t?"Porcentagem":"aumento"===t?"Aumento %":"Desconto %";window.salvarCalculo(`Calculadora de ${o}`,`Valor: ${d(n)} | %: ${e}%`,`Resultado: ${d(c)}`)}}function limparCampos(){document.getElementById("percentual").value="",document.getElementById("valor").value="",document.getElementById("resultado-area").style.display="none"}localStorage.getItem("theme")&&(document.body.setAttribute("data-theme",localStorage.getItem("theme")),document.getElementById("theme-icon").textContent="light"===localStorage.getItem("theme")?"🌙":"☀️");